import React, { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import axios from 'axios';

const TimeTrackerPage = () => {
  const location = useLocation();
  const [allEmployees, setAllEmployees] = useState([]); // Will hold ALL employees from the API
  const [isLoading, setIsLoading] = useState(true);

  // 1. Fetch ALL employees from the backend when the page loads
  useEffect(() => {
    const fetchAllEmployees = async () => {
      setIsLoading(true);
      try {
        // We fetch the full list, not a separate time tracker list
        const response = await axios.get('http://127.0.0.1:8000/api/employees/');
        if (Array.isArray(response.data)) {
          setAllEmployees(response.data);
        } else if (response.data && Array.isArray(response.data.results)) {
          setAllEmployees(response.data.results);
        }
      } catch (error) {
        console.error("Error fetching employees for time tracker:", error);
      } finally {
        setIsLoading(false);
      }
    };
    fetchAllEmployees();
  }, []); // Runs once on page load

  // 2. Get the array of selected IDs passed from the Staff Directory
  const selectedIds = location.state?.selectedEmployeeIds;

  // 3. Filter the fetched employee list based on the received IDs
  // This is a "derived state" - calculated on every render
  const employeesToDisplay = selectedIds && selectedIds.length > 0
    ? allEmployees.filter(employee => selectedIds.includes(employee.id))
    : allEmployees;

  const getStatusBadgeClass = (status) => {
    // This is a simulation, you would get this status from a different API endpoint in a real app
    const statuses = ['Working', 'Completed', 'On Leave'];
    return {
      'Working': 'bg-blue-100 text-blue-800',
      'Completed': 'bg-green-100 text-green-800',
      'On Leave': 'bg-yellow-100 text-yellow-800',
    }[status] || 'bg-gray-100 text-gray-800';
  };

  return (
    <div className="p-8">
      <div className="flex justify-between items-center mb-6">
        <div>
          <h1 className="text-3xl font-bold text-text-light dark:text-text-dark">Daily Time Tracker</h1>
          {selectedIds && selectedIds.length > 0 ? (
            <p className="text-sm text-primary font-semibold">Showing logs for {selectedIds.length} selected employee(s)</p>
          ) : (
            <p className="text-sm text-subtext-light">Showing all entries for today</p>
          )}
        </div>
        <button className="bg-primary text-white px-4 py-2 rounded-lg text-sm font-medium">Export Report</button>
      </div>

      <div className="bg-card-light dark:bg-card-dark p-6 rounded-xl shadow-sm overflow-x-auto">
        {isLoading ? (
          <div className="text-center py-8 text-subtext-light">Loading data...</div>
        ) : (
          <table className="w-full text-sm text-left">
            <thead className="text-xs uppercase bg-background-light">
              <tr>
                <th className="px-6 py-3">Employee Name</th>
                <th className="px-6 py-3">Department</th>
                <th className="px-6 py-3">Clock In</th>
                <th className="px-6 py-3">Status</th>
              </tr>
            </thead>
            <tbody>
              {employeesToDisplay.map((employee, index) => {
                // Simulating status for demonstration
                const status = ['Working', 'Completed', 'On Leave'][index % 3]; 
                return (
                  <tr key={employee.id} className="border-b hover:bg-gray-50">
                    <td className="px-6 py-4 font-medium text-text-light dark:text-white">
                      {employee.firstName} {employee.lastName}
                    </td>
                    <td className="px-6 py-4">{employee.department}</td>
                    <td className="px-6 py-4">{'09:' + String(index).padStart(2,'0') + ' AM'}</td> {/* Simulated time */}
                    <td className="px-6 py-4">
                      <span className={`px-2 py-1 text-xs font-semibold rounded-full ${getStatusBadgeClass(status)}`}>
                        {status}
                      </span>
                    </td>
                  </tr>
                )
              })}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
};

export default TimeTrackerPage;
